<div data-tabs><div class="ac-tabs"><button class="ac-tab active" type="button" data-tab-target="coupons">Coupons</button><button class="ac-tab" type="button" data-tab-target="campaigns">Campaigns</button><button class="ac-tab" type="button" data-tab-target="referrals">Referrals</button></div><section data-tab-panel="coupons" class="ac-card"><div class="ac-head"><h2>Platform coupons</h2><button class="ac-btn primary" type="button" data-open-dialog="coupon-dialog">Create coupon</button></div><div class="ac-table-wrap"><table class="ac-table"><thead><tr><th>Code</th><th>Benefit</th><th>Funding</th><th>Scope</th><th>Minimum/cap</th><th>Uses</th><th>Schedule</th><th>Status</th></tr></thead><tbody><tr><td>CRAFT20</td><td>20%</td><td>Platform</td><td>Selected crafts</td><td>₹2,000 / ₹1,000</td><td>4,821/10,000</td><td>Sep 2026</td><td><span class="ac-status success">Active</span></td></tr></tbody></table></div></section><section data-tab-panel="campaigns" hidden class="ac-card"><div class="ac-body">Homepage, category, vendor, product, event, influencer and sustainability campaigns with schedule and approval.</div></section><section data-tab-panel="referrals" hidden class="ac-card"><div class="ac-body">Qualification, return-window release, abuse detection, caps, reversals and reward ledger.</div></section></div><dialog class="ac-dialog" id="coupon-dialog"><div class="ac-dialog-head"><h2>Create platform coupon</h2><button class="ac-btn small" type="button" data-close-dialog>Close</button></div><form class="ac-body" data-admin-form="coupon"><div class="ac-form-grid"><div class="ac-field"><label for="coupon-code">Code *</label><input class="ac-input" id="coupon-code" name="code" required pattern="[A-Z0-9_-]{3,24}"></div><div class="ac-field"><label for="coupon-type">Type *</label><select class="ac-select" id="coupon-type" name="type" required><option>Percentage</option><option>Fixed amount</option><option>Delivery benefit</option></select></div><div class="ac-field"><label for="coupon-value">Value *</label><input class="ac-input" id="coupon-value" name="value" type="number" min="0" required></div><div class="ac-field"><label for="coupon-funding">Funding *</label><select class="ac-select" id="coupon-funding" name="funding" required><option>Platform</option><option>Vendor</option><option>Shared</option></select></div><div class="ac-field"><label for="coupon-start">Start *</label><input class="ac-input" id="coupon-start" name="start" type="datetime-local" required></div><div class="ac-field"><label for="coupon-end">End *</label><input class="ac-input" id="coupon-end" name="end" type="datetime-local" required></div></div><div class="ac-form-actions"><button class="ac-btn primary" type="submit">Validate coupon</button></div></form></dialog>
